    stageId: string | null;
    /**
     * Filename
     */
    fileName: string;
    /**
     * Relativepath
     *
     * where the certified bytes were found, project-relative; display only — never send it back as a project path. A run's workspace may hold an export whose name is not a portable P036 segment, and resolve_relative rejects non-ASCII segments; the artifact is addressed by its sha256, never by this string
     */
    relativePath: string | null;
    /**
     * Sha256
     */
    sha256: string | null;
    /**
     * Sizebytes
     */
    sizeBytes: number | null;
    /**
     * Objectcount
     */
    objectCount: number | null;
    /**
     * Status
     */
    status: string | null;
    /**
     * Readbackverified
     */
    readbackVerified: boolean | null;
    /**
     * Available
     */
    available: boolean;
    /**
     * Unavailablereason
     */
    unavailableReason: string | null;
    base: ProjectVersionDto | null;
    /**
     * Branchid
     */
    branchId: string | null;
    /**
     * Branchepoch
     */
    branchEpoch: number | null;
    /**
     * Programref
     */
    programRef: string | null;
    /**
     * Programdigest
     */
    programDigest: string | null;
    /**
     * Designstatedigest
     */
    designStateDigest: string | null;
    /**
     * Lengthunit
     */
    lengthUnit: string | null;
    /**
     * Upaxis
     */
    upAxis: string | null;
    /**
     * Receiptref
     *
     * the retained export receipt this row was read from; an in-process (OCCT) receipt certifies two files and is two rows sharing this ref — one exact STEP, one 3dm preview — never two candidates
     */
    receiptRef: string;
    /**
     * Format
     *
     * what a reader must know to open the file: 'step' (an exact B-rep, ISO 10303-21; download it, the viewer cannot load it) or '3dm' (what the viewer loads)
     */
    format: string;
    /**
     * Representation
     *
     * what the receipt claims the geometry is: 'exact' for the delivered model (a STEP B-rep, or a Rhino export that was read back), 'preview' for a render mesh tessellated from the exact model so it can be looked at — never a NURBS or B-rep delivery
     */
    representation: string;
    /**
     * Sourcestepsha256
     *
     * for an editable work model: the sha256 of the exact STEP its geometry was imported from, so a client can show the pair as one delivery and never load the same geometry twice
     */
