/**
 * SketchActionDto
 *
 * A profile drawn on a work plane and the height it is pulled to.
 *
 * This is the same design edit ``edit_components`` already carries — one
 * ``Element@1`` row whose producer is ``prism`` — stated in the terms the
 * person drew it in. Sending the same ``elementId`` again is how an outline
 * or a height is changed afterwards: the record keeps both as its own
 * parameters, so nothing here is a one-way conversion into geometry.
 *
 * Without a plane, points are the record's own ``(x, z)`` pairs and height
 * follows +Y. An explicit plane keeps its origin and orthonormal axes;
 * zero height is a real face and negative height reverses the pull. The
 * pointer preview stays in the browser; only a finished action arrives here.
 */
export type SketchActionDto = {
    /**
     * Componentid
     */
    componentId: string;
    /**
     * Parentcomponentid
     *
     * required when componentId is new here: the existing component it belongs under, which is what decides the seat that builds it
     */
    parentComponentId?: string | null;
    /**
     * Semantickind
     *
     * what a new component is, in the record's own vocabulary; required only when componentId is new here
     */
    semanticKind?: string | null;
    /**
     * Elementid
     *
     * the Element@1 this action authors; an existing id edits that element
     */
    elementId: string;
    /**
     * Profile
     *
     * Ordered local-plane point pairs. Closed profiles omit the repeated first point; open paths need at least two points.
     */
    profile: Array<[
        number,
        number
    ]>;
    /**
     * Closed
     *
     * True keeps the existing face/prism action; false saves an open polyline model curve and requires zero height.
     */
    closed?: boolean;
    /**
     * Height
     *
     * Signed pull distance in project length units; zero creates a planar face when closed, or an unfilled curve when open.
     */
    height: number;
    /**
     * Optional drawing frame. origin is relative to the resolved base datum; profile pairs are distances along xAxis/yAxis and positive height follows normal. Omit for the retained XZ plane.
     */
    plane?: SketchPlaneDto | null;
    /**
     * Baselevel
     */
    baseLevel?: string | null;
    /**
     * Basedatum
     */
    baseDatum?: string | null;
    /**
     * Summary
     */
    summary?: string | null;
};

