/**
 * ValidationDto
 *
 * The wire form of ``GET /api/candidates/{id}/validation``.
 */
export type ValidationDto = {
    /**
     * Candidateid
     */
    candidateId: string;
    receipt: ValidationReceiptDto;
    /**
     * Canonicalfacts
     *
     * the published references and candidate's exact retained StateRecord, including declared obligations; source presence does not mean project conditions were checked
     */
    canonicalFacts: string;
    /**
     * Validators
     *
     * every gate that ran, in the order it ran
     */
    validators: Array<string>;
    /**
     * Effectivechecks
     *
     * the gates that had anything to check on this state; narrower than validators, and never to be shown as equal to it
     */
    effectiveChecks: Array<string>;
    /**
     * Validatornote
     *
     * why the two lists differ, in a line the UI shows verbatim
     */
    validatorNote: string;
    /**
     * the candidate's own three states, copied not recomputed
     */
    relationChecks: RelationChecksDto;
    /**
     * Seatexecutioncomplete
     */
    seatExecutionComplete: boolean;
    /**
     * Reviewready
     *
     * whether all five server-owned review clauses hold; this never issues a run or advances a stage
     */
    reviewReady: boolean;
    /**
     * Blockedby
     *
     * each clause that refused, by name: validation.receipt, runner.seat_execution_complete, relations.held, relations.fully_checked, runner.exports_available
     */
    blockedBy: Array<string>;
    /**
     * Honesty
     *
     * what the submission could not carry — a seat whose program record the studio could not name is said here rather than dropped quietly; empty is a real answer, not a missing one
     */
    honesty: Array<string>;
};

